pub fn reindex_single_file(
    storage: &storage::Storage,
    repo_root: &Path,
    file_path: &str,
) -> ReindexResult {
    let path = std::path::PathBuf::from(file_path);
    // Hooks report absolute paths; entities must key on repo-relative
    // paths or every save mints a duplicate entity set under different
    // UUIDv5s. Components-normalize the relative branch too — a
    // `./src/foo.py` input must land on `src/foo.py`'s UUID.
    let rel = if path.is_absolute() {
        let root_abs = std::fs::canonicalize(repo_root).unwrap_or_else(|_| repo_root.to_path_buf());
        let stripped = path
            .strip_prefix(&root_abs)
            .map(PathBuf::from)
            .ok()
            .or_else(|| {
                std::fs::canonicalize(&path)
                    .ok()
                    .and_then(|abs| abs.strip_prefix(&root_abs).ok().map(PathBuf::from))
            });
        match stripped {
            Some(r) => r,
            None => {
                tracing::warn!("file_save reindex: {} outside repo root", file_path);
                return ReindexResult::default();
            }
        }
    } else {
        path.components()
            .filter(|c| !matches!(c, std::path::Component::CurDir))
            .collect()
    };
    let changed = vec![detection::ChangedFile {
        path: rel,
        change: detection::ChangeType::Modified,
    }];
    reindex::reindex_files(storage, repo_root, &changed)
}

fn handle_source_file_save(
    storage: &Arc<Storage>,
    config: &Config,
    cogz_dir: &Path,
    path: &str,
) -> ReindexSummary {
    let repo_root = cogz_dir.parent().unwrap_or_else(|| Path::new("."));

    tracing::debug!("file_save hook: triggering reindex for {}", path);

    let _ = config; // Config not needed for single-file reindex.
    let result = crate::index::reindex_single_file(storage, repo_root, path);

    let post = crate::index::drift::post_index_pass(storage, cogz_dir);
    let stale_flagged = post.stale_flagged;

    ReindexSummary {
        reindexed: true,
        synced: false,
        created: result.created,
        updated: result.updated,
        marked_stale: result.marked_stale,
        stale_knowledge_flagged: stale_flagged,
        embedded: 0,
    }
}

fn cleanup_stale_id_files() {
    let one_hour_ago = SystemTime::now() - Duration::from_secs(3600);
    let temp_dir = std::env::temp_dir();

    let Ok(entries) = std::fs::read_dir(&temp_dir) else {
        return;
    };

    let mut removed = 0;
    for entry in entries.flatten() {
        let path = entry.path();
        let Some(name) = path.file_name().and_then(|n| n.to_str()) else {
            continue;
        };
        if !name.starts_with("cogz-embed-bg-") || !name.ends_with(".txt") {
            continue;
        }
        if let Ok(metadata) = std::fs::metadata(&path)
            && let Ok(modified) = metadata.modified()
            && modified < one_hour_ago
            && std::fs::remove_file(&path).is_ok()
        {
            removed += 1;
        }
    }

    if removed > 0 {
        tracing::debug!("cleaned {} stale background embed ID file(s)", removed);
    }
}

