//! Subprocess-based MCP integration test.
//!
//! Spawns the real `cogz mcp-stdio` binary and communicates over
//! stdio using JSON-RPC. This catches issues that the in-process
//! tests (test_mcp_server.rs) cannot — specifically main()-level
//! concerns like tracing subscriber configuration.
//!
//! All 16 tools are exercised over the real stdio transport against
//! a temporary repo initialized via `cogz init` + `cogz index`.
//! The MCP server runs with a fake HOME so ONNX models are not
//! found — search and get_context operate in FTS-only mode, which
//! is the graceful degradation path.

use std::io::{BufRead, BufReader, Read, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};

/// Path to the cogz binary, set by Cargo for integration tests.
const COGZ_BIN: &str = env!("CARGO_BIN_EXE_cogz");

/// The CogZ repo itself — used for read-only tests against a real
/// indexed database.
const REAL_REPO: &str = env!("CARGO_MANIFEST_DIR");

/// Bound for subprocess calls that must exit on their own — a wedged
/// `cogz` child must fail the test fast, not hang the job for hours.
const SUBPROCESS_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(180);

/// Run `cogz <args> --repo <repo>` to completion with a hard timeout.
/// Kills the child and fails the test if it outlives the bound.
... (1077 more lines)

fn run_cogz_env(
    args: &[&str],
    repo: &std::path::Path,
    env: &[(String, String)],
) -> std::process::ExitStatus {
    let mut child = Command::new(COGZ_BIN)
        .args(args)
        .arg("--repo")
        .arg(repo)
        .envs(env.iter().map(|(k, v)| (k.as_str(), v.as_str())))
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn cogz");
    let deadline = std::time::Instant::now() + SUBPROCESS_TIMEOUT;
    loop {
        match child.try_wait() {
            Ok(Some(status)) => return status,
            Ok(None) if std::time::Instant::now() < deadline => {
                std::thread::sleep(std::time::Duration::from_millis(200));
            }
            Ok(None) => {
                let _ = child.kill();
                let _ = child.wait();
                panic!("cogz {args:?} timed out after {SUBPROCESS_TIMEOUT:?}");
            }
            Err(e) => panic!("cogz {args:?} wait failed: {e}"),
        }
    }
}

//! HTTP agents with bounded timeouts for all outbound requests.

use std::time::Duration;

/// Agent for small API calls — the whole call is bounded.
pub fn api_agent() -> ureq::Agent {
    ureq::Agent::config_builder()
        .timeout_per_call(Some(Duration::from_secs(30)))
        .build()
        .into()
}

/// Agent for binary downloads. Bounds connect and first-byte waits —
/// the phases that hang on dead hosts — but not the body, so slow
/// connections can still finish large downloads.
pub fn download_agent() -> ureq::Agent {
    ureq::Agent::config_builder()
        .timeout_connect(Some(Duration::from_secs(15)))
        .timeout_recv_response(Some(Duration::from_secs(60)))
        .build()
        .into()
}

